import { describe, expect, it } from 'vitest';
import { add } from '../src/math';

describe('add', () => {
  it('adds two positive numbers', () => {
    expect(add(2, 3)).toBeTypeOf('number');
  });

  it('adds a negative number', () => {
    expect(add(2, -3)).toBeTypeOf('number');
  });
});
